CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS institutions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), institution_id UUID NOT NULL REFERENCES institutions(id), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','teacher','student')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS students(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), institution_id UUID NOT NULL REFERENCES institutions(id), name TEXT NOT NULL, email TEXT NOT NULL, grade TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Activo' CHECK(status IN ('Activo','Pendiente')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(institution_id,email));
CREATE TABLE IF NOT EXISTS teachers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), institution_id UUID NOT NULL REFERENCES institutions(id), name TEXT NOT NULL, email TEXT NOT NULL, subject TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Activo' CHECK(status IN ('Activo','Pendiente')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(institution_id,email));
CREATE TABLE IF NOT EXISTS courses(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), institution_id UUID NOT NULL REFERENCES institutions(id), name TEXT NOT NULL, code TEXT NOT NULL, teacher TEXT NOT NULL, grade TEXT NOT NULL, capacity INT NOT NULL CHECK(capacity>0), students INT NOT NULL DEFAULT 0 CHECK(students>=0 AND students<=capacity), status TEXT NOT NULL DEFAULT 'Activo' CHECK(status IN ('Activo','Pendiente')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(institution_id,code));
CREATE TABLE IF NOT EXISTS enrollments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), institution_id UUID NOT NULL REFERENCES institutions(id), student TEXT NOT NULL, course TEXT NOT NULL, date DATE NOT NULL DEFAULT CURRENT_DATE, status TEXT NOT NULL DEFAULT 'Pendiente' CHECK(status IN ('Confirmada','Pendiente')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), institution_id UUID NOT NULL REFERENCES institutions(id), student TEXT NOT NULL, concept TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount>=0), date DATE NOT NULL DEFAULT CURRENT_DATE, status TEXT NOT NULL DEFAULT 'Pendiente' CHECK(status IN ('Pagado','Pendiente')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY, institution_id UUID NOT NULL REFERENCES institutions(id), user_id UUID REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_students_tenant ON students(institution_id);
CREATE INDEX IF NOT EXISTS idx_teachers_tenant ON teachers(institution_id);
CREATE INDEX IF NOT EXISTS idx_courses_tenant ON courses(institution_id);
CREATE INDEX IF NOT EXISTS idx_enrollments_tenant ON enrollments(institution_id);
CREATE INDEX IF NOT EXISTS idx_payments_tenant ON payments(institution_id);
